refentry.refsect1:
&reftitle.description;
arrayarray_intersect_assoc arrayarray arrayarrays
array_intersect_assoc ले सबै arguments मा उपस्थित array का सबै values समावेश भएको एउटा array return गर्दछ। ध्यान दिनुहोस् कि array_intersect मा जस्तो नभई, तुलना गर्दा keys पनि प्रयोग गरिन्छ।

  &reftitle.examples;



    array_intersect_assoc को उदाहरण


<?php
$array1 = array("a" => "green", "b" => "brown", "c" => "blue", "red");
$array2 = array("a" => "green", "b" => "yellow", "blue", "red");
$result_array = array_intersect_assoc($array1, $array2);
print_r($result_array);
?>


    &example.outputs;


Array
(
    [a] => green
)




  हाम्रो उदाहरणमा तपाईँले देख्नुहुन्छ कि दुवै arrays मा "a" =>
   "green" जोडी मात्र उपस्थित छ र त्यसैले यो return गरिन्छ। value "red" return गरिँदैन किनभने $array1 मा यसको key 0 छ, जबकि $array2 मा "red" को key 1 छ, र key "b" return गरिँदैन किनभने each array मा यसका values फरक छन्।
  key => value pairs from का दुई values लाई (string) $elem1 === (string) $elem2  भएको अवस्थामा मात्र बराबर मानिन्छ। अर्को शब्दमा भन्नुपर्दा, एउटा strict type जाँच गरिन्छ, त्यसैले string representation एउटै हुनुपर्छ।
